// Mulberry32: small, fast, deterministic seeded PRNG.
function makeRng(seed) {
  let s = seed >>> 0;
  return function rng() {
    s |= 0;
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function randRange(rng, min, max) {
  return min + rng() * (max - min);
}

/**
 * Build a setback skyscraper in the 1920s New York style:
 * a stack of box tiers with shrinking footprints, topped by a mast.
 *
 * @param {number} seed Seed for deterministic generation.
 * @returns {THREE.Group} Group containing the tier boxes and mast cylinder.
 */
export function buildTower(seed) {
  const rng = makeRng(seed);

  const tierCount = 4 + Math.floor(rng() * 4); // 4..7
  let width = randRange(rng, 10, 16);
  let depth = randRange(rng, 8, 14);
  let y0 = 0;

  const group = new THREE.Group();
  group.name = 'tower';

  let topY = 0;

  for (let i = 0; i < tierCount; i++) {
    const height = randRange(rng, 6, 14); // [6, 14]
    const geometry = new THREE.BoxGeometry(width, height, depth);
    const material = new THREE.MeshLambertMaterial({ color: 0xcfc5b2 });
    const mesh = new THREE.Mesh(geometry, material);

    // Tier sits exactly on the previous one, centered in xz.
    mesh.position.set(0, y0 + height / 2, 0);
    mesh.userData.tierIndex = i;

    group.add(mesh);

    y0 += height;
    topY = y0;

    // Shrink footprint for the next tier.
    width *= randRange(rng, 0.6, 0.85);
    depth *= randRange(rng, 0.6, 0.85);
  }

  // Crown mast: thin cylinder rising from the top tier's center.
  const mastHeight = randRange(rng, 3, 6);
  const mastRadius = randRange(rng, 0.15, 0.35);
  const mastGeometry = new THREE.CylinderGeometry(mastRadius, mastRadius, mastHeight, 12);
  const mastMaterial = new THREE.MeshLambertMaterial({ color: 0x333333 });
  const mast = new THREE.Mesh(mastGeometry, mastMaterial);
  mast.position.set(0, topY + mastHeight / 2, 0); // base touches top tier
  mast.userData.isMast = true;

  group.add(mast);

  return group;
}

/**
 * Extract footprint data from the tower meshes.
 *
 * @param {THREE.Group} tower Result of buildTower.
 * @returns {{width:number, depth:number, y0:number, y1:number}[]} Bottom-up list of tier footprints.
 */
export function tierFootprints(tower) {
  return tower.children
    .filter((mesh) => mesh.isMesh && !mesh.userData.isMast)
    .sort((a, b) => a.userData.tierIndex - b.userData.tierIndex)
    .map((mesh) => {
      const params = mesh.geometry.parameters;
      const height = params.height;
      const y0 = mesh.position.y - height / 2;
      return {
        width: params.width,
        depth: params.depth,
        y0,
        y1: y0 + height,
      };
    });
}
