import * as THREE from 'three';
import { buildTower, tierFootprints } from '../src/tower.js';

const EPS = 1e-9;

describe('buildTower', () => {
  it('produces between 4 and 7 tiers plus a mast', () => {
    for (const seed of [1, 2, 3, 4, 5, 42]) {
      const tower = buildTower(seed);
      const tiers = tower.children.filter((m) => m.isMesh && m.geometry?.type === 'BoxGeometry');
      const masts = tower.children.filter((m) => m.isMesh && m.geometry?.type === 'CylinderGeometry');
      expect(tiers.length).toBeGreaterThanOrEqual(4);
      expect(tiers.length).toBeLessThanOrEqual(7);
      expect(masts.length).toBe(1);
    }
  });

  it('has strictly decreasing widths and depths up the stack', () => {
    for (const seed of [1, 3, 4, 9]) {
      const fps = tierFootprints(buildTower(seed));
      for (let i = 1; i < fps.length; i++) {
        expect(fps[i].width).toBeLessThan(fps[i - 1].width);
        expect(fps[i].depth).toBeLessThan(fps[i - 1].depth);
      }
    }
  });

  it('stacks tiers contiguously: y0_{i+1} === y1_i within 1e-9', () => {
    for (const seed of [1, 3, 4, 9]) {
      const fps = tierFootprints(buildTower(seed));
      expect(fps[0].y0).toBeCloseTo(0, 9);
      for (let i = 1; i < fps.length; i++) {
        expect(Math.abs(fps[i].y0 - fps[i - 1].y1)).toBeLessThanOrEqual(EPS);
      }
    }
  });

  it('centers every tier at xz origin (Box3 center within 1e-9)', () => {
    for (const seed of [1, 3, 4, 9]) {
      const tower = buildTower(seed);
      for (const mesh of tower.children) {
        if (!mesh.isMesh || mesh.userData.isMast) continue;
        const box = new THREE.Box3().setFromObject(mesh);
        const center = box.getCenter(new THREE.Vector3());
        expect(Math.abs(center.x)).toBeLessThanOrEqual(EPS);
        expect(Math.abs(center.z)).toBeLessThanOrEqual(EPS);
      }
    }
  });

  it('is deterministic per seed but differs across seeds', () => {
    const a = JSON.stringify(tierFootprints(buildTower(3)));
    const a2 = JSON.stringify(tierFootprints(buildTower(3)));
    const b = JSON.stringify(tierFootprints(buildTower(4)));

    expect(a).toBe(a2); // same seed -> identical
    expect(a).not.toBe(b); // different seeds -> different tiers/dimensions
  });

  it('has heights in [6, 14] and shrink factors in [0.6, 0.85]', () => {
    for (const seed of [1, 3, 4, 9]) {
      const fps = tierFootprints(buildTower(seed));
      for (let i = 0; i < fps.length; i++) {
        const h = fps[i].y1 - fps[i].y0;
        expect(h).toBeGreaterThanOrEqual(6);
        expect(h).toBeLessThanOrEqual(14);
        if (i > 0) {
          const fx = fps[i].width / fps[i - 1].width;
          const fz = fps[i].depth / fps[i - 1].depth;
          expect(fx).toBeGreaterThanOrEqual(0.6);
          expect(fx).toBeLessThanOrEqual(0.85);
          expect(fz).toBeGreaterThanOrEqual(0.6);
          expect(fz).toBeLessThanOrEqual(0.85);
        }
      }
    }
  });

  it('mast base touches the top tier within 1e-6', () => {
    for (const seed of [3, 4]) {
      const tower = buildTower(seed);
      const fps = tierFootprints(tower);
      const topY = fps[fps.length - 1].y1;

      const mast = tower.children.find(
        (m) => m.isMesh && m.userData.isMast
      );
      const mastBase = mast.position.y - mast.geometry.parameters.height / 2;
      expect(Math.abs(mastBase - topY)).toBeLessThanOrEqual(1e-6);
    }
  });
});
